              "<strong>രചയിതാവും പശ്ചാത്തലവും:</strong> സമകാലിക മലയാള ചെറുകഥയിലെ ശ്രദ്ധേയയായ എഴുത്തുകാരി കെ. രേഖ (പ്രധാന കൃതികൾ: അങ്കമാലി മാങ്ങാക്കറിയും വില്ലുവണ്ടിയും മറ്റു കഥകളും, കന്യകയും പുല്ലിംഗവും, മാനാഞ്ചിറ; പുരസ്കാരങ്ങൾ: പത്മരാജൻ, രാജലക്ഷ്മി, അങ്കണം, കേരള സാഹിത്യ അക്കാദമി അവാർഡ്).",
