              "പ്രതിരോധ സിദ്ധാന്തം (Preventive Theory): കുറ്റവാളിയെ സമൂഹത്തിൽ നിന്ന് മാറ്റിനിർത്തുക വഴി (തടവ് അല്ലെങ്കിൽ വധശിക്ഷ) കുറ്റകൃത്യങ്ങൾ തടയുക.",
