            "title": "संविधान एवं राजभाषा : संवैधानिक प्रावधान",
            "chapter": "अनुच्छेद 343-351, राजभाषा अधिनियम 1963 एवं राजभाषा नियम",
            "duration": "17:08",
            "language": "Hindi",
            "youtubeId": "RDXXw4nZ-xo",
            "thumbnail": "https://i.ytimg.com/vi/RDXXw4nZ-xo/hqdefault.jpg",
            "studyPoints": [
              "<strong>संवैधानिक प्रावधान (अनुच्छेद 343):</strong> 14 सितम्बर 1949 को संविधान सभा ने हिन्दी को संघ की राजभाषा के रूप में अंगीकार किया। अनुच्छेद 343(1) के अनुसार संघ की राजभाषा हिन्दी और लिपि देवनागरी है। अंकों का रूप भारतीय अंकों का अंतर्राष्ट्रीय रूप होगा।",
              "<strong>राजभाषा आयोग एवं संसदीय समिति (अनुच्छेद 344):</strong> राष्ट्रपति द्वारा 1955 में श्री बी. जी. खेर की अध्यक्षता में प्रथम राजभाषा आयोग का गठन हुआ। 1957 में पंडित गोविंद वल्लभ पंत की अध्यक्षता में संसदीय राजभाषा समिति गठित हुई।",
              "<strong>राजभाषा अधिनियम 1963 (यथासंशोधित 1967):</strong> धारा 3(3) के तहत 14 महत्वपूर्ण प्रशासनिक दस्तावेजों (संकल्प, सामान्य आदेश, नियम, अधिसूचना, प्रशासनिक व अन्य प्रतिवेदन, अनुबंध आदि) को हिन्दी एवं अंग्रेजी दोनों में द्विभाषी जारी करना अनिवार्य है।",
              "<strong>राजभाषा नियम 1976 (क्षेत्रीय वर्गीकरण):</strong> भारत को तीन क्षेत्रों में बांटा गया है: 'क' क्षेत्र (हिन्दी भाषी राज्य), 'ख' क्षेत्र (द्विभाषी जैसे पंजाब, गुजरात, महाराष्ट्र), एवं 'ग' क्षेत्र (अहिन्दी भाषी जैसे केरल, तमिलनाडु)।",
              "<strong>अनुच्छेद 351 (हिन्दी विकास का निदेश):</strong> संघ का कर्तव्य है कि वह हिन्दी भाषा का प्रसार और विकास करे ताकि वह भारत की सामासिक संस्कृति (Composite Culture) के सभी तत्वों की अभिव्यक्ति का माध्यम बन सके।"
            ],
            "examTip": "विश्वविद्यालय परीक्षा के लिए अनुच्छेद 343 से 351, धारा 3(3) की अनिवार्यता, 'क, ख, ग' क्षेत्रों का वर्गीकरण तथा अनुच्छेद 351 के उद्देश्य 15 अंक के दीर्घ उत्तरीय (Essay) प्रश्न हेतु अत्यंत महत्वपूर्ण हैं।"
